quests[43181] = { id = 43181, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Down the Scepter", description = "The logbook contains the latest information on the Scepter of Sargeras. It appears to have been written by an extremely agitated, excited, or psychotic imp and is barely legible. Take this to Calydus for translation.", sourceObjective = "Take the logbook to Calydus in Dreadscar Rift.", sourceObjectiveStatus = "unverified-source-field" }
quests[43182] = { id = 43182, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Missing Vessel", description = "So long as Hakkar roams free, no mage will be safe.\n\nMillificent Manastorm created a vessel that siphons the essence of a mage, binding their magic to the object. It was created to be a weapon, but we can use it as bait.\n\nIf I channel my essence into the vessel, it will become an object of pure magic.\n\nUpon capture, Millificent shattered the vessel, allowing it to fall into the hands of our enemies.\n\nFind the pieces and return them to me. Together we can set a trap Hakkar won't be able to resist!", progress = "Have you found the missing pieces yet?", completion = "I am relieved that this weapon of destruction is no longer in the hands of our enemies.", objectives = "Interact with the Scouting Map and complete \"The Missing Vessel\" missions to collect Shattered Vessel Fragments.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43183] = { id = 43183, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warden Tower Assault: Starstalker's Point" }
quests[43184] = { id = 43184, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Allari the Souleater", objectives = "Very astute of you to have saved the best for last.\n\n<Allari smirks playfully.>\n\nIn all seriousness, I am deeply honored that you have chosen me, {name}. Something tells me that the worst is yet to come. We must remain vigilant and bring the Burning Legion to an end.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43185] = { id = 43185, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Jace Darkweaver", objectives = "Me? You want me to be one of your champions?\n\nYes, of course. A million times, yes! Just tell me where you want me to go, what you want me to do, and consider it done.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43186] = { id = 43186, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Am the Slayer!", description = "{name}, we have all gathered here to honor you for your leadership, successes, and sacrifices.", progress = "The Illidari and the Servants of Illidan are at your disposal.", completion = "Your leadership has provided us with victory after victory. We gladly serve and will sacrifice everything in your name.\n\nAll hail, Slayer {name}!", objectives = "Listen as you are honored by the Illidari and the Servants of Illidan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
