quests[43247] = { id = 43247, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warden Tower Assault: Darkfollow's Spire" }
quests[43248] = { id = 43248, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warden Tower Assault: Darkfollow's Spire" }
quests[43249] = { id = 43249, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Raven's Eye", description = "It is imperative that we decipher the SI:7 letter. We must uncover the secrets that it holds before it is too late. But, our best code breakers have yet to make a dent in the cypher.\n\nHowever, we now know that the myth is in fact reality. The Raven's Eye truly exists.\n\nShall we tell the others?", progress = "Are you interested, or not?", completion = "Now, what do you say you and I go to Val'sharah and recover the most powerful jewel in existence?", objectives = "Listen to Valeera's tale of the Raven's Eye.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43250] = { id = 43250, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Off to Court", description = "The Ravencourt of Black Rook Hold is where we begin our search. It is the ancestral home of Lord Kur'talos Ravencrest, night elven hero of the War of the Ancients. Some of my own ancient ancestors are interred in its cemetery.\n\nMeet me there and make sure that you are not followed. SI:7 is very good at what they do. We have to be better.", completion = "Now that you are finally here, we can begin.\n\nThe elves here have somehow risen from the dead. They are deluded. They think that we are the Burning Legion and have come here to destroy Black Rook Hold.", objectives = "Meet up with Valeera Sanguinar at Ravencourt in Val'sharah.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43251] = { id = 43251, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Search of the Eye", description = "The Raven's Eye should be somewhere within the courtyard. This is where Ravencrest's lieutenants used to plan their strategies in life. Hell, it looks like they still might be doing so in death.\n\nIt has to be around here somewhere. Your skill at lock picking should prove invaluable.", progress = "Have you found the Raven's Eye yet?", completion = "A ledger? Wait, let me look.\n\n<Valeera reaches out and begins thumbing through the tome's pages.>\n\nThis is the key!", objectives = "Pick the locks of the Ancient Chests to find the Raven's Eye.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43252] = { id = 43252, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eternal Unrest", description = "My ancient ancestors are buried here in the cemetery to the west. Because of whatever is causing the dead to rise, their souls are now at unrest.\n\nAll blood elves are descended from high elves, who in turn came from these lands before they were sundered.\n\nI cannot bring myself to do it. Will you put my ancestors to rest?", completion = "Thank you, {name}. It means a great deal to me that you have given my ancient ancestors the peace they deserve.", objectives = "Put Cesta Stargazer, Mandrel Nightsbane, and T'rel Moonblade to rest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43253] = { id = 43253, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maw of Souls: Ancient Vrykul Legends", description = "Our diversionary tactics in Stormheim uncovered intel on something I thought only a myth.\n\nThere is a legend about a magical jewel the vrykul created long before the time of man. The jewel was said to be able to...\n\n<Valeera stops herself from continuing while looking around and eyeing you wryly.>\n\nI do not want to talk about it just yet. Not until we have proof.\n\nUnfortunately, the only way we are going to get that proof is in the Maw of Souls on the Naglfar... the ship of the dead.", progress = "Did you find proof?", completion = "The legend was true! I was right about my suspicions. I had heard about Ravencrest's almost perfect espionage team during the War of the Ancients. Now we know how they got their information.\n\nThe others will not believe it when we tell them. Of course, we could keep it to ourselves.\n\n<Valeera considers for a weighty moment.>\n\nNo. That is how the foolish and greedy lose their heads. We will spread the risk around to everyone.", objectives = "Gather a group and take an etching of the Raven's Eye Tablet on the ship of the dead, The Naglfar, in the Maw of Souls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43254] = { id = 43254, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritual Ruination", description = "Time for main event, friend! Gul'dan wants to begin his big ritual, cause end times for this world. Calydus confident getting the Scepter will stop that plan.\n\nTake this bat to Tomb of Sargeras, find ritual, steal Scepter. Oh... and get out!\n\nCalydus will help when he can! Good luck, friend!", completion = "Calydus not believe that worked! Ritual messed up, Shadow Council wiped out, and we not dead!\n\nOh, and you have Scepter! Big win for friend!", objectives = "Take the Fel Bat to the Tomb of Sargeras and steal the Scepter of Sargeras.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43255] = { id = 43255, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 061 - Nastrondir" }
quests[43259] = { id = 43259, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beware of the Crooked Tree", description = "{race}, you must be warned. There is great evil in Val'sharah. I've seen it, and I wish I hadn't. If you take my advice, you will stay far away from the crooked tree in Bradensbrook.", completion = "So you've come to the crooked tree,\n\nTo name a foe you ask of me,\n\nBut listen first to my tragic tale,\n\nThen you will hear my sister's wail...", objectives = "Investigate the crooked tree in Bradensbrook.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43260] = { id = 43260, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Growing Power", description = "It appears ye and yer weapon are both growin' in strength. Return to me at Netherlight Temple. I have more to show ye.", objectives = "Use the Altar of Light and Shadow to imbue your artifact, then speak to Betild Deepanvil in Netherlight Temple.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43261] = { id = 43261, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Vanessa VanCleef", objectives = "After all that, you want me as your champion?\n\n<Vanessa gives you a look of disbelief as she takes a moment before replying.>\n\nFine, but I do things my way. Agreed?", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43262] = { id = 43262, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Garona Halforcen", objectives = "<Garona spins one of her razor-sharp blades around her fingers before deftly sheathing it at her waist.>\n\nAs long as there's a challenge to the kill, I'm game for whatever little missions you have in mind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43263] = { id = 43263, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Growing Power", description = "The bond between you and your weapon has grown stronger, Deathlord. The time has come for you to direct the flow of power within your artifact.\n\nReturn to Acherus and speak with me when you have made your choice.", objectives = "Use the Soul Forge to imbue your artifact, then speak with Highlord Darion Mograine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43264] = { id = 43264, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rise, Champions", description = "Your power is great, Deathlord, but power alone will not be sufficient.\n\nIf we are to save this world from the onslaught of the Burning Legion, then you will need powerful allies. The Knights of the Ebon Blade are yours to command, it will be wise to make use of them effectively.\n\nGo and speak with Nazgrim and Thassarian. They will be of great use to you in the fight against the Burning Legion.", completion = "Well done, Deathlord. Nazgrim and Thassarian are powerful champions. I am sure they will carry out their orders with deadly precision.", objectives = "Recruit Nazgrim and Thassarian.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43265] = { id = 43265, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spread the Word", description = "Now that you have recruited your champions, you can use the Scouting Map to complete vital missions across the Broken Isles.\n\nThe first mission is critical to the growth and power of our order. Send Nazgrim and Thassarian to seek out new candidates for the Ebon Blade.\n\nOur order must grow in strength if we are to defeat the Burning Legion.", progress = "What is the status of the mission?", completion = "It appears that Nazgrim and Thassarian were successful in their mission. We have identified several promising candidates to aid us in the war against the Burning Legion.", objectives = "Use the Scouting map and complete \"Spread the Word.\"", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43266] = { id = 43266, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recruiting the Troops", description = "A powerful necromancer has joined the cause of the Ebon Blade.\n\nDark Summoner Marogh has come a long way to us from deep within the realm of the Shadowlands. He will be a powerful ally of the Ebon Blade.\n\nSpeak with Dark Summoner Marogh to begin raising an army of ghouls for the Ebon Blade.", progress = "Has Dark Summoner Marogh begun his work?", completion = "Good work, Deathlord.\n\nThese ghouls will be invaluable in the war effort on the Broken Isles. Deploy them on missions just as you would your other champions.", objectives = "Speak with Dark Summoner Marogh to summon ghouls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43267] = { id = 43267, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Troops in the Field", description = "It's time to send our newly summoned ghouls out into the field. Look at the Command Table and send your champions and troops on a routine scouting mission.", progress = "How did it go?", completion = "Excellent work, Deathlord. The mission was a complete success.\n\nWith continued success in the field, the Burning Legion will surely be beaten back.", objectives = "Use the Command Table and complete the mission, \"Troops in the Field.\"", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43268] = { id = 43268, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tech It Up A Notch", description = "Archivist Zubashi has been doing a great deal of research on the necropolis we call Acherus.\n\nThrough his studies on the necropolis, he has located a number of potential improvements that can greatly increase the power of the Ebon Hold.\n\nSpeak with Archivist Zubashi now and he will show you what improvements can be made.", progress = "Greetings, Deathlord. I have been studyin' da true nature of da necropolis. You going to be pleased wit' da results I assure you!", completion = "That was an excellent choice, Deathlord. Feel free to speak to Zubashi whenever you require further upgrades.", objectives = "Speak with Archivist Zubashi in Acherus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43270] = { id = 43270, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rise, Champions", description = "As leader of our order, other priests will look to you for guidance. Many will be willing to pledge themselves to you, doing whatever is necessary to bring down the Burning Legion.\n\nAfter your display of power during the cleansing ritual, there will be many who are eager to serve at your side. Seek out those priests, and let them ease the burden of leadership.", completion = "Excellent. Calia Menethil and High Priestess Ishanah are worthy champions. We can trust them to carry out any task we ask of them.", objectives = "Recruit Calia Menethil and High Priestess Ishanah.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43271] = { id = 43271, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Calia Menethil", objectives = "Well met, {name}. It's an honor to serve at your side.\n\nI'm happy to help in any way I can.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43272] = { id = 43272, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: High Priestess Ishanah", completion = "Your efforts to restore Saa'ra have not gone unnoticed. As a humble servant of the Sha'tar, I thank you.\n\nAs leader of the Aldor, it is my duty to safeguard all that is holy. This temple is a beacon of light that must be protected.\n\nYou can count me among your allies, willing to do whatever is necessary to destroy the Burning Legion." }
quests[43273] = { id = 43273, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spread the Word", description = "In the center of the dais is a map of the Broken Isles. From it, you can direct our allies to carry out vital assignments across the world.\n\nThe first task is critical to the growth of our order - identifying skilled priests whom we can trust to train our order's troops.\n\nThis is a task we can easily entrust to one of our new champions.", progress = "How is the mission proceeding?", completion = "Calia's mission was a success! We may be seeing some new faces around here soon.", objectives = "Use the Command Map and complete the mission, \"Spread the Word\".", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43274] = { id = 43274, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "reuse me" }
quests[43275] = { id = 43275, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recruiting the Troops", description = "Our recruiting efforts have paid off. Grand Anchorite Gesslar has pledged his service to our order.\n\nHe has an eye for greatness, and can easily spot a recruit with potential. He takes those selected under his wing, and shapes them into worthy allies.\n\nSpeak to him now and train a troop of acolytes.", progress = "How did the training go?", completion = "Excellent. These troops will be invaluable in our defense of the Broken Isles. Deploy them on missions, just as you would with our champions.", objectives = "Speak to Grand Anchorite Gesslar and train a troop of acolytes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43276] = { id = 43276, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Troops in the Field", description = "It's time to send our newly trained acolytes out into the field. Look at the Command Map and send your champions and troops on a routine scouting mission.", progress = "How did it go?", completion = "The scouting mission was more successful than we could have imagined, {name}.\n\nYour troops were able to rescue Archon Torias, a skilled researcher whose knowledge extends far beyond light and shadow.\n\nIn thanks, he has agreed to lend his expertise to our cause.", objectives = "Use the Command Map and complete the mission, \"Troops in Training\".", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43277] = { id = 43277, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tech It Up A Notch", description = "We are very fortunate to have come across Archon Torias.\n\nHis knowledge will be invaluable as we improve our defenders and fortify Netherlight Temple.", progress = "Have you had a chance to speak with Archon Torias yet?", completion = "Excellent choice, {name}. Archon Torias will continue to conduct his research in Netherlight Temple. Speak to him when you want to make additional upgrades.", objectives = "Speak to Archon Torias in Netherlight Temple.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
