quests[43303] = { id = 43303, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Time to Rumble!", description = "Welcome to the Black Rook Rumble!  Many combatants have entered to prove their might in the Black Rook Arena, and now it is your time.", objectives = "Speak with David Globerunner and find out how to participate in the Black Rook Rumble.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
