quests[43307] = { id = 43307, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 070 - Outskirts" }
quests[43308] = { id = 43308, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 071 - Outskirts" }
quests[43309] = { id = 43309, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Perfect Opportunity", description = "I have heard whispers from Suramar City.\n\nRecent unrest in the city has prompted the nobles to seek another advisor to fill Elisande's council. Such positions are rarely offered and hotly contested.\n\nThis is the perfect opportunity and Ly'leth is the perfect candidate. Fate smiles upon our cause!\n\nI know she has historically chosen to avoid such politics and maneuvering, but we must now ask her to join the fray.\n\nSeek her out at the Waning Crescent and ensure her victory.", progress = "Thalyssra asks much of me.", completion = "Ahh, {name}.\n\nSo good to see you once again. I trust you are ready to assist me with my campaign.", objectives = "Meet Ly'leth Lunastre at the Waning Crescent.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43310] = { id = 43310, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Either With Us", description = "Thalyssra asks much of me, but our cause is worth the risks.\n\nThe title of advisor would grant us enormous influence. Information. Access.\n\nI could change this rebellion. I could save so many lives.\n\nI will need strong endorsement to ascend, though. There are many houses who stand with me by virtue of my family's name. Some are more hesitant.\n\nLady Aurore of House Astravar is the most prominent of these. Seek her out. Offer your aid in my stead. \n\nEarn her trust and the rest will follow.", completion = "I love Lady Lunastre like a sister, but I am afraid my hands are tied.", objectives = "Speak to Lady Aurore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43311] = { id = 43311, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Or Against Us", description = "If Ly'leth is to achieve the role of advisor to the Grand Magistrix we will need to open a path for her.\n\nIt is true she will have some supporters but they alone cannot grant her the title.\n\nThere are other houses that Ly'leth must contend with. Fear and coercion are their tools. None dare stand against them openly, and we cannot win them over with favors and oaths. \n\nSeek out Arluin. I trust he will have some ideas of how to proceed.", progress = "Yes, I know why you are here. Yes, I can get the jobe done. No, it will not be free.", completion = "Very well. Let us talk strategy.", objectives = "Speak to Arluin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43312] = { id = 43312, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thinly Veiled Threats", description = "How could I let this happen?\n\n<Aurore wrings her hands.>\n\nYesterday Coryn Stelleris approached me about the appointment. He sought my support, but I did not offer it. \n\nHe said my son's life would continue as normal... if I gave him my vote.\n\nThis morning my son was gone.\n\nI can only think of the terrible things he may be suffering. You know what this family is capable of!\n\nYou want my support, but I can do nothing while my son is in danger. Nothing.\n\nPlease... save him!", progress = "Did you find my son?", completion = "He is unharmed! I owe you- and Ly'leth- a great debt.", objectives = "Rescue Ailen Astravar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43313] = { id = 43313, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rumor Has It", description = "Coryn Stelleris and Ruven Duskmere were close friends, but one always overshadowed the other. Now the Stelleris family stands to gain from lord Ruven's death. Handsomely.\n\nHouse Duskmere will soon learn of their loss. I want you to be the one to redirect their anger and grief.\n\nA handful of well placed rumors should do the trick.\n\nI won't be lingering in this part of the city for long, and Ly'leth will want to know of your efforts.\n\nReturn to her when you are finished.", completion = "The city is buzzing with very interesting gossip, {name}. Victory is that much closer.", objectives = "Plant rumors among members of House Duskmere.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43314] = { id = 43314, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Court of Stars: Beware the Fury of a Patient Elf", description = "An opportunity presents itself, {name}.\n\nLy'leth has arranged to grant you entry into a ball at the Court of Stars. I do not know what we may gain from this venture, but there is one task I must set for you.\n\nAdvisor Melandrus once called himself my ally. He and I planned Elisande's downfall, but when the moment came I found myself betrayed.\n\nThe wound his dagger inflicted still aches. I cannot enter Suramar to take my revenge, but you can.\n\nGive him a traitor's death, and bring me his spellstone.", progress = "Is it done?", completion = "<Thalyssra clutches the spellstone tightly for a moment.>\n\nHe brought this upon himself.\n\nI cannot linger in the past. Elisande is weaker without him, and we are one step closer to righting the wrongs inflicted upon the shal'dorei.", objectives = "Enter the Court of Stars dungeon and slay Advisor Melandrus. Collect his Spellstone and return it to Thalyssra.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43315] = { id = 43315, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Death Becomes Him", description = "There are two houses that pose a threat to Ly'leth's rise, but we concern ourselves with only one of them now.\n\nHouse Duskmere commands respect through fear and that fear is not unfounded. Few can boast of magical talent equal to that of Ruven Duskmere. \n\nWithout this charming specimen, however, their house is nothing.\n\nI know you may find my methods distasteful. Know that there were demons in Suramar long before the Legion.\n\nThis one has lived long enough.", progress = "Is it done?", completion = "It seemed as though you had that well in hand. I did not want to... interrupt.\n\nThat is one less power hoarding noble to worry about. Well done, {name}.", objectives = "Slay Ruven Duskmere.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43316] = { id = 43316, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "By Invitation Only", description = "While you were keeping His Highness busy, I found something of interest to Ly'leth and the others.\n\n<Arluin dangles a colorful, elaborately decorated scroll in front of you.>\n\nIt is an invitation. To a party. A party which all of the Suramar nobility will be attending.\n\nNot least on the guest list is Grand Magistrix Elisande herself.\n\nIf you are thinking what I am thinking, then you would agree that Ly'leth needs to know about this.\n\nImmediately.", sourceObjective = "Bring Ly'leth Lunastre the Hand-Scribed Invitation.", sourceObjectiveStatus = "unverified-source-field" }
quests[43317] = { id = 43317, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In the Bag", description = "Already the city is abuzz with outrage.\n\nI will not lie to you- it pleases me greatly that one such as Coryn is made a fool.\n\nThe other houses have sent their endorsements. It is done, and nothing remains but a formal ceremony to grant me the title of advisor.\n\nMeet me there. You deserve to share in this success.", progress = "I am prepared. It is nearly time.", completion = "This may not end as cleanly as I would have preferred.", objectives = "Witness Ly'leth Lunastre's ascension to advisor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43318] = { id = 43318, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ly'leth's Champion", description = "Tal'ashar is an honor duel.\n\nIf I lose, then I must forfeit my title to Coryn Stelleris.\n\n<Ly'leth smiles gently.>\n\nThat is why you are going to fight for me. \n\nI will grant you a more powerful disguise for this task, and together we will put Coryn in his place.\n\nSpeak to me when you are ready to battle on my behalf.", progress = "I know you will defend my honor, {name}.", completion = "We made great strides today. I will not forget this.", objectives = "Speak with Ly'leth to begin the encounter.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43319] = { id = 43319, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Way of the Tiger", description = "Among the allies who joined us from Tian Monastery is Gin Lai, a monk famed for his experience in the ways of the tiger.\n\nWith his help, we will be able to train Tiger Initiates, who strike swiftly and precisely on the field of battle.\n\nGo speak with him now and request his services.", completion = "I will do my best to teach the way of the tiger, Grandmaster: to observe the enemy, and strike without hesitation. Soon, our initiates will be ready for battle.", objectives = "Speak to Recruiter Gin Lai.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43323] = { id = 43323, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Time to Reflect", description = "It is time to reflect on the events that have brought us to this moment. A celebration of our great history and the events that shape it.", progress = "Let us speak, then, of events that have already come to pass.", completion = "A moment to reminisce on how far we have come. A day to look to the future and where we might go. A year of reflection on what it means to grow and a lifetime of memories made by those brave enough to seize it.", objectives = "Correctly answer one of Llore's questions about the history of Azeroth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43324] = { id = 43324, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rage of the Owlbeasts" }
quests[43325] = { id = 43325, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ley Race" }
quests[43326] = { id = 43326, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scouting" }
quests[43327] = { id = 43327, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Magic of Flight" }
quests[43328] = { id = 43328, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enigmatic" }
quests[43330] = { id = 43330, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fire for Effect" }
quests[43331] = { id = 43331, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Time to Collect", description = "Hey there, pal. My sources around here say you had a run-in with the Sixtrigger brothers. I'd imagine you're not very happy with them?\n\nLet's just say we're not exactly friends either.\n\nSo I'll tell you what. How about I let you in on some intel about their current location? Maybe they might have an unfortunate accident, you follow?\n\nOh, and bring some friends. They're not exactly the easiest of targets.", progress = "This seems to be where the Sixtrigger brothers keep their most prized spoils.", completion = "With the Sixtrigger brothers ended, you're finally able to collect your payment for services rendered.\n\nYou rummage through their most prized possessions and take your pick.", objectives = "Collect Sixtrigger's Key from Rax Sixtrigger in Stormheim.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43332] = { id = 43332, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grell in a Handbasket" }
quests[43333] = { id = 43333, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "DANGER: Nylaathria the Forgotten" }
quests[43334] = { id = 43334, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Coming Storm", description = "You saved us all, my friend! Truly you embody all the elements stand for.\n\nIf the Earthen Ring is to prevail, we will need weapons of great power. I know where to find some. After the Pandaren Campaign, the weapons of the storm god Ra-den were discovered beneath the Throne of Thunder. None have been able to wield them, so great is their power.\n\nThey were placed in the care of the White Tiger, who will give them only to one who is worthy. Come {name}! Travel with me to Pandaria and we will prove your worth!", completion = "Welcome {class}! You seek the weapons of the storm god Ra-den?\n\nMany have traveled here to Pandaria, but none have proven themselves worthy.", objectives = "Travel to Pandaria and speak to the White Tiger at his temple.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43335] = { id = 43335, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Survival Skills", description = "The life of a hunter should never be dull. Living in the wild you never know what will happen next, but you survive on skill and instinct.\n\nShow me you have the basic survival skills to live off the land.", progress = "You need to eat to survive in the wild.\n\nBoar meat makes an excellent meal when cooked over an open flame. It should not be eaten raw, however.\n\nThere are many berries that grow in this region. Some are edible, while others cause minor sickness when ingested. You can often tell which are safe to eat by their smell. A sweet aroma often indicates the berry is unsafe to eat.\n\nThe best firewood can be obtained from dying trees. They are easily identified by their fading, purple leaves.", completion = "You built your campfire with ease, and put a perfect sear on that steak. I'm impressed... and hungry.", objectives = "Show your survival skill by building a campfire from chopped wood, and cooking a steak over an open flame.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43336] = { id = 43336, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Purge of the Nightmare" }
quests[43337] = { id = 43337, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Met Sylvanas With Windrunner Bow" }
quests[43338] = { id = 43338, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Codex of Ra", description = "The Thunder King conquered Pandaria using power stolen from the Titan Keeper Ra, known as \"Ra-den\" in the mogu tongue. If you truly seek to wield the relics of the Highkeeper, seek out his ancient edicts among the ruins in the heart of the mogu empire: The Edict of Stone, The Edict of Fire, and the Edict of the Storm.\n\nThese pieces of the codex are scattered amongst the Guo-Lai Halls in the Vale of Eternal Blossoms, one in each wing.", progress = "I've been asking around. The pandaren locals are terrified of this place. It's been haunted since the end of Hellscream's Pandaren Campaign.\n\nDid you find an offering for the White Tiger?", completion = "That tiger is serious about this, isn't he?\n\nWhile you were here, others came to the Temple of the White Tiger to present their offerings to him. It looks like we're going to have some competition.", objectives = "Enter the Guo Lai Halls in the Vale of Eternal Blossoms and collect the Edict of Stone, the Edict of Fire, and the Edict of the Storm. Cleanse the area by slaying mogu spirits.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43340] = { id = 43340, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[43341] = { id = 43341, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uniting the Isles", description = "There are a great number of factions here on the Broken Isles. We must unite them if we want to stand a chance against the Legion. Prove your worth to them and report back to me.", progress = "Any luck uniting the factions?", completion = "Excellent work, {name}. We still have a long road ahead of us to rid this world of the Legion, but this brings us one step closer.", objectives = "Earn at least Friendly reputation with the factions of the Broken Isles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43342] = { id = 43342, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette - Roteye" }
quests[43343] = { id = 43343, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Dread-Rider Cortis" }
quests[43344] = { id = 43344, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "DANGER: Aodh Witherpetal" }
quests[43345] = { id = 43345, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "DANGER: Harbinger of Screams" }
quests[43346] = { id = 43346, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "DANGER: Ealdis" }
quests[43347] = { id = 43347, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "DANGER: Rabxach" }
quests[43348] = { id = 43348, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Magister Phaedris" }
quests[43349] = { id = 43349, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Aegis of Aggramar", description = "Now that it's out of the hands of the Legion, the Aegis should be brought back to Dalaran for safekeeping while the hunt continues for the rest of the Pillars of Creation.\n\nIt should be safe in the central portal chamber until the time comes when it is needed.", completion = "The Aegis of Aggramar is secure within the well-defended city of Dalaran.\n\nYour quest to drive back the Legion is one step closer to fruition.", objectives = "Secure the Aegis of Aggramar in the Chamber of the Guardian in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43351] = { id = 43351, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mal'Dreth the Corrupter" }
quests[43352] = { id = 43352, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Asset Security", description = "With the demons and guards so agitated, I'm running out of safe places to store contraband. The guards have caught on to one of my favorite havens and will be making off with my goods any minute now.\n\nHead to my stash and discourage their curiosity. You will need to use a grappling hook to access it- just look for something to latch onto along the ledge.\n\nI will make sure there is something in it for you when you are done.", progress = "Did you deter them yet?", completion = "You're becoming quite the dependable associate.", objectives = "Defend Arluin's stash from the city guards.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43353] = { id = 43353, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Celestine of the Harvest" }
quests[43354] = { id = 43354, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Thisalee Crow" }
quests[43355] = { id = 43355, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Matoclaw" }
quests[43356] = { id = 43356, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Talza" }
quests[43357] = { id = 43357, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Graham Silverclaw" }
quests[43358] = { id = 43358, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Myonix" }
quests[43359] = { id = 43359, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Hero's Weapon", description = "Grand Master, you have saved our order from the brink of destruction.\n\nYour deeds have shown us that with effort and determination we can overcome any challenge. In light of your example, we have doubled our efforts and developed a technique that will awaken your weapon to its true potential.\n\nPlease, stand before the Forge of the Roaring Mountain and raise your weapon high.", progress = "We honor you, Grandmaster.", completion = "May the new powers of your weapon aid you in the times ahead.", objectives = "Approach the indicated location before the Forge of the Roaring Mountain and raise your weapon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43360] = { id = 43360, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shardmaidens", description = "Long have I walked this land and I have seen many forms of corruption.\n\nThe creatures that wander this hall are twisted by the magics unleashed by the failed arcan'dor. These dryads have lost their way, and cannot be saved.\n\nYou must destroy them. End their suffering.", completion = "Thank you. This place will never recover, but their madness need not harm others.", objectives = "Slay 6 Shardmaidens in the Shattered Locus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43361] = { id = 43361, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fragments of Disaster", description = "In the hall beyond rests the bones of the failed arcan'dor.\n\nI will take fragments of the crystallized tree and attempt to read them. We must discover the root cause of this destruction.\n\nOnly then do we have any hope of preventing this disaster from repeating itself.", progress = "Do you have the shards?", completion = "I will study these carefully. If we are fortunate, there will be answers.", objectives = "Collect 5 Crystallized Bark.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43362] = { id = 43362, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Stuff of Dreams", description = "This arcan'dor is one of an ancient species. They were not bred, but created. In them the arcane and primitive druidic magics merged into something greater than both.\n\nThe arcane will soon devour it whole.\n\nWe can restore balance, but it will require wild magic. Magic trapped in another realm.\n\nYou must enter the Emerald Dreamway and bring back the essence of life itself.\n\nOnly then can the arcan'dor find stability and begin to thrive once more.", progress = "Do you have it?", completion = "I do not know how you obtained this, but I know it was not easy. Much stands against us, but you prevailed. Come. Let us restore the arcan'dor.", objectives = "Collect Purified Life Essence from the Emerald Dreamway.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43363] = { id = 43363, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Winter Veil Gift", objectives = "A small tag on this present reads:\n\nHappy holidays, {name}!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43364] = { id = 43364, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gently Shaken Gift", objectives = "This present looks like it has been shaken a few times. The tag on it reads:\n\nTo a very special {race} {class}.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43365] = { id = 43365, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Cycle Continues", description = "Yay! The grove is regenerating nicely. Our flower friends thank you for helping them.\n\nWe were able to save most of the grove, but sadly, many living souls were lost as well.\n\nBrightwing is so sad!\n\nBut you can help! Take this bag of Dream Seeds. Plant them onto fresh corpses, and in time, new flowers will grow!\n\nDeath is beautiful, and from death comes rebirth. This is the cycle that must continue!", completion = "Thank you... it gives Brightwing much peace to know that life continues.", objectives = "Plant 100 Dream Seeds on corpses.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43366] = { id = 43366, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talked with Mimiron" }
quests[43367] = { id = 43367, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pixie Dust", description = "Friend, you have done so much for Brightwing, but there is still so much more to do.\n\nI've been working so hard to restore the grove, but my magic is drained.\n\n<Brightwing's stomach grumbles loudly.>\n\nWithout magic, my work cannot continue. The enchanters of your people use a magical dust that can revitalize me quickly.\n\nIf you bring me some, I can work much faster!", objectives = "Bring 50 Arkhana to Brightwing. Arkhana is obtained through the enchanting profession.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43368] = { id = 43368, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Brightwing", objectives = "Your heroic efforts within the Emerald Dream were inspiring, {name}. The Dream is safe for now, but it remains threatened as long as Xavius lives.\n\nI will lend you my aid. Together, let us keep Azeroth safe from those who would seek its destruction.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43369] = { id = 43369, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Siegemaster Aedrin" }
quests[43370] = { id = 43370, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A New Invention", description = "I have been experimenting with technology that allows you to alter the structure of beasts, specifically with how they look.", progress = "This is my most magnificent invention I have made. In the last 10 minutes.", completion = "Here you go, {name}. Take care of Hati and the Titanstrike and be safe in your adventures.", objectives = "I should be able to create an item that allows you to change the appearance of Hati, but the components for such an item are rare. The Squallhunters from Stormheim have a Stormy Gland, and the Stoneblood Harpies near Thas'talah in Val'sharah have Pristine Harpy Feathers that I need. The Hatecoil Naga near the Ruins of Nar'thalas in Azsuna are said to have Reflective Scales, and finally I need an Essence of Pure Spirit from the Seabound Mystics in the Blind Marshlands of Highmountain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43371] = { id = 43371, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Relieving the Front Lines", description = "Many within our order have been on the front lines of battle for too long, aiding those who are attempting to thwart the Legion's invasion.\n\nIt is time we send in some relief, allowing our allies some much needed rest.", completion = "Hopefully our priests have a chance to rest before heading back into battle.", objectives = "Interact with the Command Map and complete the mission, \"Relieving the Front Lines\".", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43372] = { id = 43372, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Whispers in the Void", description = "Our priests are resting and recuperating, but one not as well as the others. Gilner Greymoss lingers within the Sanctuary of the Void, laughing to himself.\n\nHe refuses to leave, but his presence is making the other priests uneasy.\n\nPerhaps you should speak to him and see what is wrong?", progress = "Some wounds are too deep to heal.", completion = "Gilner's hearing voices, is he? All that dabbling in the shadows has finally caught up to him.", objectives = "Speak to Gilner Greymoss in the Sanctuary of the Void.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43373] = { id = 43373, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Best and Brightest", description = "If we wish to see the truth in Gilner's ramblings, I will need to induce a vision.\n\nIt is not the sort of thing that is typically forced, but we have within our ranks the best and brightest alchemists who can craft an extract that will grant me the sight I need.\n\nSeek them out in Azsuna where they are currently aiding those on the front lines.", completion = "It's a good thing ya showed up when you did.\n\nSo Velen wants to induce a vision? That's no easy task, but it's nothing Yalia and I can't handle.", objectives = "Find Zabra Hexx in Azsuna.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43374] = { id = 43374, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Murloc Mind Control", description = "Yalia and I were deliverin' antidotes to da front lines a Faronaar when we were attacked by a herd a murlocs. We dropped our supplies and made a run for it, but Yalia never made it out a da camp. Obviously I didn't fair much better, ma bones still ache from bein' turned to stone.\n\nIt's possible Yalia's still alive and bein' held captive. Please, ya have to find her!", completion = "Your quick thinking got me out of a terrible situation. Thank you, {name}.", objectives = "Rescue Yalia Sagewhisper from the murlocs within El'dranil Shallows.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43375] = { id = 43375, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Ample Supply", description = "Durin' our attempt to flee da murlocs, Yalia and I dropped da supplies we planned to deliver to da demon hunters in Faronaar.\n\nInside each a those crates were vials a salve dat took us countless days and resources to craft. If we don' get those supplies back, I fear our allies on da front lines will suffer.", progress = "Do ya have our supplies?", completion = "There's no tellin' how many lives ya saved by recoverin' these vials.", objectives = "Recover Felbat Toxin Salve from supply crates scattered around El'dranil Shallows.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43376] = { id = 43376, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Problem Salver", description = "Forcing a vision isn't easy by any means. Finding the ingredients for the elixir alone will take a considerable amount of time, time we don't have. Too many are suffering on the front lines as we speak, in need of the salve we were meant to deliver.\n\nI suppose if we all work together, we can make this work.\n\nZabra and I will find the items needed for Velen's elixir, if you take the salve to Faronaar and cure the demon hunters. Does that sound fair?", completion = "We've found the ingredients we'll need for Velen's elixir.", objectives = "Use the salve on diseased demon hunters at Faronaar Front in Azsuna.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43377] = { id = 43377, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Halls of Valor: The Light Within", description = "We cannot ignore the Prophet's vision, {name}. To do so would mean that everything we know and hold dear will be lost to the Legion.\n\nWe must focus on what we know, and that is that the Light must walk among us.\n\nWithin the Halls of Valor you will find an ascending val'kyr by the name of Hyrja. Recover a spark of her Light and release it within our temple.", completion = "<Saa'ra's soothing voice fills your mind.>\n\nYour gift of Light is a welcome one, {class}.", objectives = "Recover a Spark of Light from Hyrja within the Halls of Valor dungeon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43378] = { id = 43378, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eye of Azshara: Looking Through the Lens", description = "We have what we need to create Velen's elixir, but in order for others to be able to witness his vision, we'll need to find something that can be used to project images from the mind.\n\nA lens from the nearby naga should work well, but I don't think they're going to be too eager to give it up.", progress = "Gazing through the lens of a powerful naga will allow you to witness my vision.", completion = "You've returned, and just in time it would seem.\n\nYalia and Zabra have just finished crafting the elixir. This lens will allow you to see what I see when the vision begins.", objectives = "Recover the Lens of the Tide from Lady Hatecoil within the Eye of Azshara dungeon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43379] = { id = 43379, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Velen's Vision", description = "I have everything I need to bring forth a vision, but the question remains: are you ready to witness it? Even the smallest glimpse into the future can weigh heavy on your soul.\n\nOnce I ingest the elixir, the vision will come quickly. Gazing into the Lens of the Tides will allow you to see what I see.\n\nLet me know when you are ready to begin.", progress = "Even the smallest glimpse into the future can leave a heavy weight on your mind.", completion = "We will not let this demon determine our fate. You have the power to change our future.\n\nI have seen the path to salvation, and you will lead us there.\n\nI must retire for now. The weight of this vision has taken its toll on my mind and body.", objectives = "Use the Lens of the Tides to witness Prophet Velen's vision.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43380] = { id = 43380, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Sol", objectives = "Born of Light, I fight for Light.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43381] = { id = 43381, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Mariella Ward", objectives = "I owe you my life, and so much more.\n\nYou saw something in me worth saving, and allowed me to eventually believe that as well.\n\nLet me live my life with purpose, {name}. Let me fight by your side.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43382] = { id = 43382, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Natalie Seline", objectives = "You pulled my spirit from the Void, which is no easy feat. I cannot deny the part of me that would stay there forever, embraced by the shadows.\n\nThe Void is filled with many whispers, {name}. The kind that should have us all worried.\n\nWe cannot afford to be separated by our beliefs. We must come together as priests of both Light and Shadow to face the Burning Legion together.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43383] = { id = 43383, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Awakening the Light", description = "This spark will only know its full potential once it's been filled with pure Light, gleaned from the holiest places in our world.\n\nNurture this spark, and it may grow to walk among you.", progress = "<Saa'ra's soothing voice fills your mind.>\n\nNurture the spark with holy Light if you wish it to awaken and walk among you.", completion = "<The room begins to warm as the Light expands.>", objectives = "Collect Pure Holy Light by completing Class Hall missions.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43384] = { id = 43384, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Demonic Runes", description = "I cannot stand by idly and allow the Legion to destroy our home. \n\nI've been studying their language for some time, deciphering any runes I can get my hands on, but my supply is severely limited. \n\nIf I had more runes to study, it's possible that I may discover something that will help us in locating Balnazzar.", progress = "Were you able to recover the runestones?", completion = "These are in excellent condition! Thank you, {name}.", objectives = "Collect Demonic Runestones from demons throughout the Broken Isles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43385] = { id = 43385, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infiltrating Our Enemies", description = "With the Light at our side, we should focus our efforts on figuring out who among our enemies could be a potential ally.\n\nAny of your champions should be capable of infiltrating enemy ranks, giving us a better understanding of how to approach this.\n\nEven so, it is a delicate task. Proceed with caution.", completion = "Your efforts have provided us with the information we need to move forward.\n\nIt's been discovered that there are a few defectors among the Scarlet Onslaught.", objectives = "Interact with the Command Map and complete the mission, \"Infiltrating Our Enemies\".", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43386] = { id = 43386, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Onslaught Envoy", description = "A few defectors have been discovered among the Scarlet Onslaught in Northrend.\n\nI know it's difficult to think that any within their ranks could be useful to our cause, but we must make an attempt.\n\nThe prophecy says an old enemy will become an ally, so it's worth it to investigate and see if these defectors can be brought to the Light.", completion = "Why are you here? Why bother saving me? I was prepared to die. I should pay for the terrible things I've done...", objectives = "Find a new ally among old enemies in New Hearthglen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43387] = { id = 43387, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scarlet Redemption", description = "The Light shines upon me, {name}! For the first time in my life, I feel it!\n\nI was without hope, ready to die for the things I had done in the name of the Scarlet Crusade, but then you appeared! You are my chance at redemption. \n\nPlease, let me prove to you that I am worthy of a second chance. Let me slay those I used to be loyal to!", progress = "I will prove myself worthy of being redeemed.", completion = "The Light truly shines upon me, {name}. Your presence has proven that.", objectives = "Help Mariella the Heretic redeem herself by killing members of the Scarlet Onslaught in New Hearthglen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43388] = { id = 43388, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Apostate Liberation", description = "There are others like me, you know. Others that have removed the veil that the Scarlet Crusade has kept over our eyes for so long. \n\nThey've been placed in cages, treated like animals, simply because their beliefs no longer line up with what the Onslaught deems is right and holy. \n\nThey wish to redeem themselves. We should try to free them, if you think their lives are worth saving.", progress = "All we want is a chance to redeem ourselves.", completion = "The mercy you have shown brings tears to my eyes.", objectives = "Rescue Onslaught Apostates within New Hearthglen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43389] = { id = 43389, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unexpected Guests", description = "You helped me escape my fate by freeing me from the gallows, but allowing me to fight the Scarlet Onslaught by your side has truly freed my heart and mind from the guilt I have felt for so long.\n\nI want to be a part of something greater than myself, a noble cause that won't distort the meaning of the Light. \n\nLet me travel to your temple and beg forgiveness of the Prophet. I may not be a welcome guest, but it's a journey I must make to complete my redemption.", completion = "Is this the enemy we should welcome as an ally?", objectives = "Return to Alonsus Faol in Netherlight Temple.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43390] = { id = 43390, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forgotten Shadows", description = "The Light walks among us, as does one of our enemies. You have done well to bring the prophecy to life, but it is not yet complete.\n\nThe shadows must rise, and to do so, the Cult of Forgotten Shadows must be restored. \n\nYou will find the few remaining followers at the cemetery in Duskwood. They linger there near the grave of their fallen leader.", completion = "Alonsus sent you, did he? He's never shown much interest in us before.\n\nOf course, we've never been ones to follow the Light, at least not in the way that most would want us to.\n\nWe embrace the Shadows as well, finding our faith in the balance between both extremes.", objectives = "Head to Duskwood and meet with a member of the Cult of Forgotten Shadows.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43391] = { id = 43391, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secrets of the Void", description = "Our leader was murdered for her beliefs, or so most would believe.\n\nNatalie Seline knew her fate, and took steps to protect herself from an inevitable death. \n\nThe night her attackers came, Natalie sent her spirit to the Void, its location known only to Natalie herself.\n\nShe penned a spell to retrieve it in one of her many journals, but the tome has since fallen into the hands of those who wished her dead in the first place.\n\nWithout her journal, we will never be able to recover her spirit.", progress = "We watch over Natalie's body, forever hopeful that her spirit will return.", completion = "This is it! This is the journal that contains the spell to locate Natalie's spirit!", objectives = "Recover Natalie's Journal from Twilight Lord Urgrok.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43392] = { id = 43392, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Void", description = "This is without a doubt Natalie's writing. The entry was scrawled in haste, but the message is clear: The spell within this journal will lead us to Natalie's spirit, but it needs to be incanted at a shadow altar within the catacombs.\n\nOdessa and I have a duty to watch over Natalie's body, but with your considerable power, you should be able to perform the spell with ease.", completion = "The lure of the Void is strong. There were times I thought I would be lost there forever.\n\nThank you for freeing me, {name}.", objectives = "Read Natalie's Journal at the catacomb's shadow altar to enter the void and recover her spirit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
